values
  ('f215304f-469d-4031-9008-516c7b299f38','zh-tw','workman-jang-sung-gyu','《Workman》張聖圭「尺度爆表」','張聖圭主持的網路綜藝《Workman》，靠體驗各種職業時尺度爆表的吐槽爆紅','《Workman》是Studio Lululala於2019年5月17日首播的網路綜藝節目，以親身體驗各種職業為主軸，搭配主持人張聖圭毫不收斂的吐槽風格，獲得爆炸性迴響。同年7月獨立成專屬頻道，成長速度之快，甚至登上YouTube Rewind 2019「最速竄紅創作者」第2名。','Studio Lululala網路綜藝《Workman》首播（2019年5月）','用來形容機智地稍微越線的吐槽',null,array['워크맨 선넘규','張聖圭Workman','尺度爆表張聖圭'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
on conflict (meme_id, locale) do nothing;

