values
  ('90c32145-5e91-4bb0-a9de-4cc3dfac13e3','zh-tw','lim-yo-hwan-emperor-of-terran','임요환(Lim Yo-hwan)「泰蘭皇帝」','星海爭霸職業選手임요환的別名，2001年電競巨星誕生','以帳號「SlayerS_BoxeR」活動的임요환，用當時被視為最弱種族的人類族（Terran），在2001、2002年連續兩屆世界電子競技大賽（WCG）奪冠，因此獲得「泰蘭皇帝」的別名。他是韓國電競草創時期最頂尖的明星，掀起全民級的風潮。','源自星海爭霸職業選手임요환的比賽戰績與粉絲圈而生的別名','用於電競草創期歷史、星海爭霸回顧內容',null,array['임요환 "테란의 황제"','皇帝','BoxeR'],'[{"text":"這位選手根本임요환泰蘭皇帝等級的氣場","situation":"KakaoTalk"},{"text":"聊電競歷史當然要從임요환開始講起","situation":"社群留言"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
