  ('3e691e5f-5688-4052-9449-ca1ca3c7dce6','zh-tw','holy-war-kang-min-ma-jae-yoon','聖戰','星海爭霸討論版命名的강민 對 마재윤 宿敵對戰','在神族（Protoss）苦於對抗蟲族（Zerg）的年代，被視為唯一能與蟲族最強者마재윤匹敵的강민，兩人的對決被星海爭霸討論版稱為「聖戰」。這兩位選手的比賽被視為攸關種族尊嚴的特殊對決，是伴隨2006年前後마재윤全盛期而廣為流傳的說法。','星海爭霸討論版用語，指마재윤全盛期（約2006年）與강민的對決','用於指稱攸關種族尊嚴的宿敵對決',null,array['성전','강민 마재윤 聖戰'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
on conflict (meme_id, locale) do nothing;

