  (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by)
values
  ('07c54d12-212d-495c-905c-44953a331332','zh-tw','hey-mama-challenge','Hey Mama挑戰','Mnet《舞孃來了》隊長任務編舞，於2021年演變成全球性TikTok挑戰','2021年8至10月播出的Mnet《舞孃來了》隊長任務中，WAYB隊舞者노제為David Guetta的歌曲〈Hey Mama〉編舞並演出。這支編舞在TikTok上演變成「Hey Mama挑戰」，吸引K-pop偶像與海外舞者相繼參與，成為2021年下半年代表性的短影音內容之一。','Mnet《舞孃來了》隊長任務，舞者노제編舞（2021年播出內容）','適合用來談論舞者強烈的表演或生存實境秀熱潮時使用',null,array['헤이마마 챌린지','舞孃來了Hey Mama','노제 Hey Mama'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
on conflict (meme_id, locale) do nothing;

