  (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by)
values
  ('b131ee97-8ec6-4646-8252-5783f86571f9','zh-tw','three-consecutive-bunker-rush','삼연벙（三連速攻）','임요환對홍진호連續三次成功施展速攻戰術的傳奇比賽','指2004年11月12日EVER星海聯賽2004四強第2週，임요환對홍진호連續三次成功施展速攻戰術（bunker rush）的比賽與策略。在對方陣地蓋兵營、提早結束比賽的戰術，竟然連續成功了三次而引發話題。之後意義擴大，也泛指連續三次施展或遭受某種行為的情況。','2004年11月12日EVER星海聯賽2004四強，임요환對홍진호之戰','用於相同情況或行為連續發生三次時',null,array['삼연벙','三連벙','三連速攻'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
on conflict (meme_id, locale) do nothing;

