values
  ('6ae6b4c5-694b-4bf3-a1d8-08263fabcee4','zh-tw','bts-dynamite-challenge','BTS〈Dynamite〉挑戰','跟著防彈少年團2020年首支全英文單曲〈Dynamite〉招牌動作跳的TikTok挑戰','防彈少年團於2020年8月21日發行的首支全英文歌曲〈Dynamite〉，特色是副歌撥髮的動作，以及向Michael Jackson〈Billie Jean〉致敬的踏步舞步。發行同時，以「#DynamiteChallenge」為主題標籤的TikTok翻跳挑戰在全球擴散開來。','防彈少年團單曲〈Dynamite〉（2020年8月21日發行）編舞','適合用來談論2020年代表性的全球舞蹈挑戰時使用',null,array['다이너마이트 댄스 챌린지','BTS 다이너마이트 챌린지','Dynamite挑戰','BTS Dynamite舞蹈挑戰'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
on conflict (meme_id, locale) do nothing;

